+/** Per item between two days (inclusive): theoretical use from sales, actual use from `consume` movements, and actual minus theoretical. */
+export function varianceReport(store, from, to) {
+  const theoretical = theoreticalUse(store, from, to);
+  const actual = new Map();
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !batchItem.has(m.batchId)) continue;
+    const day = dayOf(m.at);
+    if (day < from || day > to) continue;
+    const itemId = batchItem.get(m.batchId);
+    actual.set(itemId, (actual.get(itemId) ?? 0) + m.qty);
+  }
+  const round3 = (n) => Math.round(n * 1000) / 1000;
+  return [...new Set([...theoretical.keys(), ...actual.keys()])]
+    .map((itemId) => {
+      const t = round3(theoretical.get(itemId) ?? 0);
+      const a = round3(actual.get(itemId) ?? 0);
+      return { itemId, theoretical: t, actual: a, difference: round3(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0)
+    .sort((a, b) => a.itemId - b.itemId);
+}
