+// Sales from the till. Each sale line is one dish sold `qty` times; a dish
+// uses one portion of its recipe per `qty`. Tickets are imported once.
+import { AppError } from "../errors.js";
+import { dayOf } from "../dates.js";
+import { consume } from "./batches.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** Every imported sale line, in id order. */
+export function listSales(store) {
+  return [...(store.data.sales ?? [])].sort((a, b) => a.id - b.id);
+}
+
+/**
+ * Books sale lines ({ row, ticket, soldAt, dishId, qty }): consumes each dish's ingredients (ref
+ * `sale:<ticket>`, at `soldAt`) and keeps the lines. Tickets already known are skipped; on any
+ * error nothing is booked and the error names the row. Returns { tickets, dishes } booked.
+ */
+export function recordSales(store, lines) {
+  const dishes = store.data.dishes ?? [];
+  const planned = lines.map((line) => {
+    const dish = dishes.find((d) => d.id === line.dishId);
+    if (!dish) throw new AppError("bad_request", { reason: `row ${line.row}: unknown dish` });
+    return { ...line, needs: scaled(getRecipe(store, dish.recipeId), line.qty) };
+  });
+  const known = new Set((store.data.sales ?? []).map((s) => s.ticket));
+  const fresh = planned.filter((p) => !known.has(p.ticket));
+  const snapshot = structuredClone(store.data);
+  try {
+    for (const line of fresh) {
+      for (const need of line.needs) {
+        if (!(need.qty > 0)) continue;
+        try {
+          consume(store, need.itemId, need.qty, { at: line.soldAt, ref: `sale:${line.ticket}` });
+        } catch (e) {
+          if (e instanceof AppError && e.code === "not_enough_stock")
+            throw new AppError("sale_not_enough_stock", { ...e.params, available: round3(e.params.available), row: line.row });
+          if (e instanceof AppError && e.code === "unknown_item")
+            throw new AppError("bad_request", { reason: `row ${line.row}: the recipe uses unknown item ${need.itemId}` });
+          throw e;
+        }
+      }
+      store.data.sales ??= [];
+      store.data.sales.push({ id: store.nextId("sale"), ticket: line.ticket, soldAt: line.soldAt, dishId: line.dishId, qty: line.qty });
+    }
+  } catch (e) {
+    store.data = snapshot;
+    throw e;
+  }
+  return { tickets: new Set(fresh.map((l) => l.ticket)).size, dishes: fresh.reduce((s, l) => s + l.qty, 0) };
+}
+
+/** Theoretical use per item (Map itemId → qty) from sales sold between two days (inclusive). */
+export function theoreticalUse(store, from, to) {
+  const byItem = new Map();
+  for (const sale of store.data.sales ?? []) {
+    const day = dayOf(sale.soldAt);
+    if (day < from || day > to) continue;
+    const dish = (store.data.dishes ?? []).find((d) => d.id === sale.dishId);
+    const recipe = dish && store.data.recipes.find((r) => r.id === dish.recipeId);
+    if (!recipe) continue;
+    for (const need of scaled(recipe, sale.qty)) byItem.set(need.itemId, round3((byItem.get(need.itemId) ?? 0) + need.qty));
+  }
+  return byItem;
+}
